export const DependencyDirection = {
  blocks: 'blocks',
  'blocked-by': 'blocked-by',
} as const;

export interface DependencyCreation {
  otherTaskKey: TaskKey;
  direction: DependencyDirection;
}

/**
 * A directed edge between visible tasks in the current organization.
 */
export interface Dependency {
  id: string;
  blocker: TaskSummary;
  blocked: TaskSummary;
}

/**
 * Visible edges ordered by creation time and ID.
 */
export interface DependencyPage {
  items: Dependency[];
  nextCursor: NextCursor | null;
}

/**
 * A recipient identified by account, not spelling. Offsets count Unicode code points in
 * the unchanged Markdown, zero-based, start inclusive and end exclusive. Spans must be
 * non-overlapping, in range, and cover a nonempty displayed token beginning with `@`.
 * Raw text without a span never identifies a recipient. The recipient must be a current
 * member, including a guest, with read access to the task's list after the write.
 */
export interface Mention {
  userId: string;
  /** @minimum 0 */
  start: number;
  /** @minimum 1 */
  end: number;
}

/**
 * A live comment in the flat task timeline; deleted comments are omitted.
 */
export interface Comment {
  id: string;
  taskKey: TaskKey;
  actor: Actor;
  /** The submitted Markdown source, unchanged. */
  body: string;
  createdAt: string;
  /** @nullable */
  editedAt: string | null;
  /** @minimum 1 */
  version: number;
  mentions: Mention[];
  /**
     * Immutable reply target, retained even when that comment is deleted.
     * @nullable
     */
  replyToCommentId: string | null;
}

/**
 * Live comments ordered by creation time and ID, oldest first; total excludes tombstones.
 */
export interface CommentPage {
  items: Comment[];
  nextCursor: NextCursor | null;
  /** @minimum 0 */
  total: number;
}

/**
 * A comment and optional structured mentions and reply target.
 */
export interface CommentCreation {
  /**
     * Markdown of 1 to 5,000 Unicode code points, not whitespace only; stored unchanged.
     * @minLength 1
     * @maxLength 5000
     * @pattern \S
     */
  body: string;
  /** @maxItems 20 */
  mentions?: Mention[];
  /** A live comment on this same task. */
  replyToCommentId?: string;
}

/**
 * JSON Merge Patch. Replacing the body clears existing mention spans unless a replacement
 * array is supplied. A spans-only change still requires the comment's If-Match. Undeclared
 * members are ignored.
 */
export interface CommentPatch {
  /**
     * Markdown of 1 to 5,000 Unicode code points, not whitespace only; stored unchanged.
     * @minLength 1
     * @maxLength 5000
     * @pattern \S
     */
  body?: string;
  /** @maxItems 20 */
  mentions?: Mention[];
}

/**
 * A current member eligible for a mention on this task, including guests.
 */
export interface TaskParticipant {
  userId: string;
  memberId: string;
}

/**
 * Eligible accounts ordered by user ID.
 */
export interface TaskParticipantPage {
  items: TaskParticipant[];
  nextCursor: NextCursor | null;
}

/**
 * An effective watcher who currently has task access.
 */
export interface Watcher {
  userId: string;
}

/**
 * Effective watchers ordered by user ID, with the same total and caller state on every page.
 */
export interface WatcherPage {
  items: Watcher[];
  nextCursor: NextCursor | null;
  /** @minimum 0 */
  total: number;
  callerFollows: boolean;
}

/**
 * Prefix of the keys of a space ("Préfixe", "De 2 à 5 lettres, sans accent."): 2 to 5
 * uppercase letters A to Z.
 * @pattern ^[A-Z]{2,5}$
 */
export type SpacePrefix = string;

/**
 * `organization` ("Tout Atelier Nord") or `private` ("Privé", the lock "Espace privé"), as a
 * space carries it. Later versions may add values (`x-extensible-enum`): a client treats an
 * unknown one as `private`.
 */
export type VisibilityValue = string;

/**
 * Category of a status: `open` ("Non commencé": `triage`, `backlog`, `todo`), `active`
 * ("Actif": `progress`, `review`, `testing`, `waiting`, `blocked`) or `closed` ("Fermé":
 * `done`, `cancelled`). `STATUS_CATEGORIES` and `STATUS_CATEGORY_BY_KEY` of
 * `@cadenway/contracts`; the category of a key never changes.
 */
export type StatusCategory = typeof StatusCategory[keyof typeof StatusCategory];


export const StatusCategory = {
  open: 'open',
  active: 'active',
  closed: 'closed',
} as const;

/**
 * How a space shows one status ("Statuts de « Produit »").
 */
export interface SpaceStatus {
  category: StatusCategory;
  /**
     * The name the space gives the status, 24 characters at most; `null` for its default
     * label, for example "À faire" for `todo`.
     * @nullable
     */
  name: string | null;
  /**
     * Whether the space no longer uses the status ("Ne plus utiliser …"): it leaves the
     * status menus and the list groups, but a task that has it keeps it. Always `false` for
     * `todo` and `done`.
     */
  hidden: boolean;
}

/**
 * The ten statuses as the space shows them, by key.
 */
export interface SpaceStatuses {
  triage: SpaceStatus;
  backlog: SpaceStatus;
  todo: SpaceStatus;
  progress: SpaceStatus;
  review: SpaceStatus;
  testing: SpaceStatus;
  waiting: SpaceStatus;
  blocked: SpaceStatus;
  done: SpaceStatus;
  cancelled: SpaceStatus;
}

/**
 * A space ("Espace"): the lists and sprints of a team or a domain, the prefix of their task
 * keys, its appearance, who sees it and how it names its statuses. `nextKey` is the key the
 * next task created in the space would take now ("Les tâches seront numérotées CAD-1,
 * CAD-2…"), a preview that reserves nothing: another creation may take it first.
 */
export interface Space {
  id: string;
  /** "Nom de l’espace", 80 characters at most. */
  name: string;
  prefix: SpacePrefix;
  /**
     * "Description", 500 characters at most; `null` when there is none.
     * @nullable
     */
  description: string | null;
  icon: LookIconValue | null;
  color: LookColorValue;
  visibility: VisibilityValue;
  owner: UserRef;
  statuses: SpaceStatuses;
  nextKey: TaskKey;
  createdAt: string;
  /**
     * Version of the space, also sent as `ETag`; a change of its grants adds one too.
     * @minimum 1
     */
  version: number;
  /**
     * The role of the caller on the space itself (see "Access" in
     * `openapi/public/spaces.yaml`): the highest of the rule of the organization, the owner
     * of the space and a grant of the space. `null` when the caller sees the space only
     * through the grants of some of its lists, as a guest does: they see those lists only,
     * and create no list in the space. Absent, it reads as `edit`, the rule before grants
     * existed.
     */
  callerRole?: AccessRoleValue | null;
  /**
     * Whether the caller manages the space: changes its visibility, shares it and deletes it;
     * its settings and statuses need `edit` only. `true` for the owner of the space, and for
     * the owner and the admins of the organization when the space is `organization`. Absent,
     * the web application offers the actions and handles their `403`.
     */
  callerCanManage?: boolean;
}

